CommonData.BannerCustomCSS:
#onetrust-banner-sdk * {
    font-family: Aeonik, sans-serif !important;
  }

  /* Banner container - rounded card for center/middle position */
  #onetrust-banner-sdk {
    border-radius: 8px !important;
  }

  /* Title */
  #onetrust-banner-sdk #onetrust-policy-title {
    font-size: 20px !important;
    font-weight: 500 !important;
    line-height: 28px !important;
    letter-spacing: 0.1px !important;
    color: #191919 !important;
    text-align: left !important;
    margin: 0 0 16px 0 !important;
    padding: 0 !important;
  }

  /* Policy text */
  #onetrust-banner-sdk #onetrust-policy-text {
    margin: 0 0 32px 0 !important;
    font-size: 14px !important;
    font-weight: 400 !important;
    line-height: 20px !important;
    letter-spacing: 0.21px !important;
    color: rgba(0, 0, 0, 0.66) !important;
    text-align: left !important;
  }

  /* Policy container - reset any padding/margin that misaligns title */
  #onetrust-banner-sdk #onetrust-policy {
    padding: 0 !important;
    margin: 0 !important;
  }

  /* Links */
  #onetrust-consent-sdk #onetrust-banner-sdk a[href] {
    color: rgba(0, 0, 0, 0.66) !important;
    margin-left: 0;
    font-weight: normal;
    text-decoration: underline;
  }

  #onetrust-consent-sdk #onetrust-banner-sdk a[href]:hover {
    color: #42464d !important;
  }

  /* All buttons base styles */
  #onetrust-consent-sdk #onetrust-accept-btn-handler,
  #onetrust-banner-sdk #onetrust-reject-all-handler,
  #onetrust-banner-sdk #onetrust-pc-btn-handler {
    border-radius: 6px !important;
    font-weight: 500 !important;
    font-size: 16px !important;
    line-height: 24px !important;
    letter-spacing: 0.32px !important;
    padding: 12px 32px !important;
    min-width: auto !important;
    margin: 0 !important;
    transition: all 0.2s ease;
    white-space: nowrap;
  }

  /* Primary buttons (Accept all, Reject all) */
  #onetrust-consent-sdk #onetrust-accept-btn-handler,
  #onetrust-banner-sdk #onetrust-reject-all-handler {
    background-color: #191919 !important;
    border: 1.5px solid #191919 !important;
    color: #fffefa !important;
    opacity: 1 !important;
  }

  #onetrust-consent-sdk #onetrust-accept-btn-handler:hover,
  #onetrust-banner-sdk #onetrust-reject-all-handler:hover {
    background-color: #3f59e4 !important;
    border-color: #3f59e4 !important;
    color: #fffefa !important;
    opacity: 1 !important;
  }

  /* Secondary button (Cookie settings) - outlined */
  #onetrust-consent-sdk #onetrust-pc-btn-handler,
  #onetrust-consent-sdk #onetrust-pc-btn-handler.cookie-setting-link {
    background-color: transparent !important;
    border: 1.5px solid #191919 !important;
    color: #191919 !important;
    margin-right: auto !important;
  }

  #onetrust-consent-sdk #onetrust-pc-btn-handler:hover {
    border-color: #3f59e4 !important;
    color: #3f59e4 !important;
  }

  /* Button group layout - Cookie settings left, Accept/Reject right */
  #onetrust-banner-sdk #onetrust-button-group {
    display: flex !important;
    align-items: center !important;
    gap: 8px !important;
    width: 100% !important;
    max-width: 100% !important;
    padding: 0 !important;
  }

  /* Gap between Reject all and Accept all */
  #onetrust-banner-sdk .banner-actions-container {
    display: flex !important;
    align-items: center !important;
    gap: 12px !important;
  }

  /* Container padding */
  #onetrust-banner-sdk .ot-sdk-container {
    padding: 24px 32px 32px !important;
    width: 100% !important;
  }

  /* Layout - vertical flow */
  #onetrust-banner-sdk .ot-sdk-row {
    display: flex;
    flex-direction: column;
    margin: 0 auto;
  }

  #onetrust-banner-sdk:not(.ot-iab-2) #onetrust-group-container {
    padding: 0;
    margin: 0;
    position: relative;
    width: 100% !important;
  }

  #onetrust-banner-sdk:not(.ot-iab-2).vertical-align-content
    #onetrust-button-group-parent {
    width: 100%;
    padding: 0;
    margin: 0;
    position: relative;
    top: 0;
    bottom: 0;
    transform: none;
  }

  #onetrust-banner-sdk:not(.ot-iab-2) #onetrust-button-group-parent {
    width: 100% !important;
    padding: 0 !important;
    margin: 0 !important;
  }

  #onetrust-banner-sdk:focus {
    outline: none;
  }

  #onetrust-banner-sdk .ot-sdk-column,
  #onetrust-banner-sdk .ot-sdk-columns {
    margin-left: 0 !important;
    width: 100% !important;
  }

  #onetrust-banner-sdk .ot-sdk-three.ot-sdk-columns {
    padding: 0 !important;
  }

  /* Tablet styles - stacked buttons same width */
  @media only screen and (min-width: 701px) and (max-width: 1024px) {
    #onetrust-banner-sdk #onetrust-button-group {
      flex-direction: column !important;
      align-items: stretch !important;
      gap: 8px !important;
    }

    #onetrust-banner-sdk .banner-actions-container {
      flex-direction: column !important;
      align-items: stretch !important;
      gap: 8px !important;
    }

    #onetrust-consent-sdk #onetrust-pc-btn-handler,
    #onetrust-consent-sdk #onetrust-pc-btn-handler.cookie-setting-link {
      margin-right: 0 !important;
    }

    #onetrust-consent-sdk #onetrust-accept-btn-handler,
    #onetrust-banner-sdk #onetrust-reject-all-handler,
    #onetrust-banner-sdk #onetrust-pc-btn-handler,
    #onetrust-banner-sdk .has-reject-all-button #onetrust-pc-btn-handler,
    #onetrust-banner-sdk .has-reject-all-button .banner-actions-container {
      max-width: 100% !important;
    }
  }

  /* Mobile styles */
  @media only screen and (max-width: 700px) {
    /* Push banner to bottom of screen */
    #onetrust-banner-sdk {
      top: auto !important;
      bottom: 0 !important;
      left: 0 !important;
      right: 0 !important;
      transform: none !important;
      border-radius: 8px 8px 0 0 !important;
      max-width: 100% !important;
      width: 100% !important;
    }

    #onetrust-consent-sdk #onetrust-accept-btn-handler,
    #onetrust-banner-sdk #onetrust-reject-all-handler,
    #onetrust-banner-sdk #onetrust-pc-btn-handler,
    #onetrust-banner-sdk .has-reject-all-button #onetrust-pc-btn-handler,
    #onetrust-banner-sdk .has-reject-all-button .banner-actions-container {
      max-width: 100% !important;
    }

    #onetrust-banner-sdk .ot-sdk-container {
      padding: 16px !important;
    }

    /* Hide title on mobile */
    #onetrust-banner-sdk #onetrust-policy-title {
      display: none !important;
    }

    /* Mobile text */
    #onetrust-banner-sdk #onetrust-policy-text {
      font-size: 12px !important;
      line-height: 18px !important;
      letter-spacing: 0.21px !important;
      color: #191919 !important;
      margin: 0 0 12px 0 !important;
    }

    /* Stack buttons vertically with 8px gap */
    #onetrust-banner-sdk #onetrust-button-group {
      flex-direction: column !important;
      align-items: stretch !important;
      gap: 8px !important;
    }

    /* Stack Reject/Accept vertically with 8px gap on mobile */
    #onetrust-banner-sdk .banner-actions-container {
      flex-direction: column !important;
      align-items: stretch !important;
      gap: 8px !important;
    }

    /* Reset margin-right on Cookie settings for mobile stacking */
    #onetrust-consent-sdk #onetrust-pc-btn-handler,
    #onetrust-consent-sdk #onetrust-pc-btn-handler.cookie-setting-link {
      margin-right: 0 !important;
    }

    /* Smaller buttons on mobile, full width */
    #onetrust-consent-sdk #onetrust-accept-btn-handler,
    #onetrust-banner-sdk #onetrust-reject-all-handler,
    #onetrust-banner-sdk #onetrust-pc-btn-handler {
      font-size: 14px !important;
      line-height: 20px !important;
      letter-spacing: 0.21px !important;
      padding: 8px 32px !important;
      width: 100% !important;
    }
  }

